'use strict';

// The landing pages (index.html, ja/index.html, en/index.html) are generated by
// scripts/build-landing.js from scripts/landing/content.js. This test fails when the
// committed HTML is stale, and checks a few things the page must keep.

const assert = require('assert');
const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');

const root = path.join(__dirname, '..');

execFileSync(process.execPath, [path.join(root, 'scripts', 'build-landing.js'), '--check'], { stdio: 'inherit' });

const pages = [
  ['index.html', './'],
  ['en/index.html', '../'],
  ['ja/index.html', '../'],
];

for (const [file, prefix] of pages) {
  const html = fs.readFileSync(path.join(root, file), 'utf8');

  // Every local asset and page the landing page links to must exist.
  const refs = new Set();
  for (const match of html.matchAll(/(?:src|href)="(\.\.?\/[^"#?]*)/g)) refs.add(match[1]);
  for (const ref of refs) {
    const target = path.join(root, path.dirname(file), decodeURI(ref));
    assert.ok(fs.existsSync(target), `${file}: missing local target ${ref}`);
  }

  // SUPER VIRTUAL HURDLE is playable straight from the hero.
  assert.ok(html.includes(`class="lp-hero-media" href="${prefix}examples/GAME-SUPER-HURDLE/"`), `${file}: hero must link to SUPER VIRTUAL HURDLE`);

  // Hardware comes before "How it works", so the page reads as an ORPHE CORE page first.
  assert.ok(html.indexOf('id="core-specs"') < html.indexOf('id="how-it-works"'), `${file}: hardware section must precede how-it-works`);

  // Anchors that other pages and old links point at.
  for (const id of ['start-in-3-minutes', 'what-you-can-build', 'examples', 'starter-templates', 'motion-intelligence', 'workshop', 'shoelace-mount', 'core-specs']) {
    assert.ok(html.includes(`id="${id}"`), `${file}: missing anchor #${id}`);
  }

  // Both languages ship in every page.
  assert.ok(html.includes('class="ja"') && html.includes('class="en"'), `${file}: both languages must be present`);
}

console.log('landing-build-sync.test.js: ok');
